-- Human-readable demo IDs and imported source IDs share the same key space
-- with UUIDs generated by the application.
alter table public.drafts drop constraint drafts_opportunity_id_fkey;
alter table public.opportunities alter column id type text using id::text;
alter table public.drafts alter column id type text using id::text;
alter table public.drafts alter column opportunity_id type text using opportunity_id::text;
alter table public.runs alter column id type text using id::text;
alter table public.events alter column id type text using id::text;
alter table public.drafts add constraint drafts_opportunity_id_fkey
  foreign key (opportunity_id) references public.opportunities(id);
